const $=id=>document.getElementById(id), names=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];
const note=n=>names[n%12]+(Math.floor(n/12)-1), freq=n=>440*2**((n-69)/12);
let ctx,voices=[],playToken=0,mode='match',pool=[],target=[],selection=[],slot=0,done=false,number=0,stats={total:0,correct:0};
try{stats=JSON.parse(localStorage.getItem('ear-garden-stats'))||stats}catch{}
function updateStats(){$('stats').textContent=stats.correct+' / '+stats.total}updateStats();
async function audio(){ctx??=new(window.AudioContext||window.webkitAudioContext)();await ctx.resume()}
function stop(){playToken++;voices.forEach(v=>{try{v.stop()}catch{}});voices=[];document.body.classList.remove('playing')}
function tone(n,t,d=.75){const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq(n);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.18,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+d+.04);voices.push(o);if($('timbre').value==='soft'){const h=ctx.createOscillator(),a=ctx.createGain();h.frequency.value=freq(n)*2;a.gain.setValueAtTime(.035,t);a.gain.exponentialRampToValueAtTime(.001,t+d*.65);h.connect(a).connect(ctx.destination);h.start(t);h.stop(t+d);voices.push(h)}}
async function play(ns,simultaneous=false){try{stop();const token=playToken;await audio();if(token!==playToken)return;const start=ctx.currentTime+.04;document.body.classList.add('playing');ns.forEach((n,i)=>tone(n,start+(simultaneous?0:i*.85)));setTimeout(()=>{if(playToken===token)document.body.classList.remove('playing')},(simultaneous?1:ns.length)*850)}catch{$('feedback').textContent='声音未能启动，请点击播放按钮再试一次，并检查设备音量。'}}
const ranges={
  '3':{notes:[0,2,4],guide:'已熟悉 C、D、E？下一步选「新音 · F G A」，不用一下跳到 7 个音。'},
  fga:{notes:[5,7,9],guide:'先单独熟悉 F、G、A。能稳定找到后，选「认识 B · G A B」；也可以回到「4 个音」逐个混入旧音。'},
  gab:{notes:[7,9,11],guide:'用刚熟悉的 G、A 作参照，认识 B。之后从「4 个音」开始，逐步混合 C 到 B。'},
  '4':{notes:[0,2,4,5],guide:'在 C、D、E 中只加入 F。多比较 E 与 F，熟悉后再选「5 个音」加入 G。'},
  '5':{notes:[0,2,4,5,7],guide:'这次只加入 G。先试听每个琴键，再听目标；熟悉后选「6 个音」加入 A。'},
  '6':{notes:[0,2,4,5,7,9],guide:'这次只加入 A。若混合后容易混淆，可以回到 F G A 小组再练，之后才加入 B。'},
  '7':{notes:[0,2,4,5,7,9,11],guide:'最后加入 B，混合练习 7 个自然音。不用急着去掉试听，也不用急着挑战半音。'},
  '12':{notes:Array.from({length:12},(_,i)=>i),guide:'加入升降音的半音挑战。如果跨度太大，随时回到 7 个自然音。'}
};
const random=n=>Math.floor(Math.random()*n);
const info={match:['找到，那个相同的音。','先听目标音，再逐个试听下方的琴键。','找音不是考试。反复试听和逐个尝试，就是耳朵学习的过程。'],direction:['听见声音的方向。','两个音依次响起。第二个比第一个更高，还是更低？','先关注高低，不必记音名。可以用手比划声音上行或下行。'],bass:['一点点，拆开低音线。','听完整短句，再依次点 3 个音，自动填入三个音位。','这里练的是低音音符。真实歌曲的最低音不一定是和弦根音。'],chord:['听听和弦的性格。','同一根音，大三与小三。先试听示范，再判断目标。','两种三和弦只差一个三音。别急着用情绪命名，直接比较声音。']};
function newQuestion(reviewEntry=null,continueRound=false){stop();done=false;slot=0;selection=[];number++;const base=+$('register').value,range=ranges[$('difficulty').value]||ranges['3'];pool=range.notes.map(n=>base+n);$('range-guide').textContent=range.guide;$('range-guide').hidden=['direction','chord'].includes(mode);target=reviewEntry?.id?[...reviewEntry.target]:makePracticeTarget(base,pool);$('title').textContent=info[mode][0];$('subtitle').textContent=info[mode][1];$('tip').textContent=info[mode][2];$('question-no').textContent='第 '+String(number).padStart(2,'0')+' 题';$('play').innerHTML='▶ <span>'+({match:'播放目标音',bass:'播放低音短句',direction:'播放两个音',chord:'播放目标和弦'}[mode])+'</span>';$('difficulty-label').hidden=['direction','chord'].includes(mode);$('feedback').textContent='先听一遍，再开始找。慢慢来。';$('submit').hidden=false;$('next').hidden=true;$('reveal').hidden=false;$('review').hidden=true;$('answer-label').textContent=mode==='direction'?'判断走向':mode==='chord'?'比较与选择':'探索琴键';$('answer-hint').textContent=mode==='chord'?'先试听示范，再选择；示范与目标根音相同':mode==='direction'?'只需判断方向，不需要知道音名':mode==='bass'?'依次选 3 个音，自动跳到下一音位':'点琴键选答案；仅试听请点 ♫';setupRecordQuestion(reviewEntry?.id?reviewEntry:null);beginPracticeQuestion(!!reviewEntry?.id,continueRound);render()}
function chord(kind){return [target[0],target[0]+(kind===0?4:3),target[0]+7]}
function expected(){return mode==='direction'?[Math.sign(target[1]-target[0])+1]:mode==='chord'?[target[1]]:target}
function render(){const seq=$('sequence');seq.replaceChildren();if(mode==='bass')for(let i=0;i<3;i++){const b=document.createElement('button');b.className=i===slot?'selected':'';b.textContent='第 '+(i+1)+' 音 · '+(selection[i]===undefined?'待选':note(selection[i]));b.setAttribute('aria-pressed',String(i===slot));b.onclick=()=>{slot=i;render()};seq.append(b)}if(mode==='bass'){
const filled=Array.from({length:3},(_,i)=>selection[i]!==undefined).filter(Boolean).length;
$('bass-help').hidden=false;$('bass-help').textContent=done?'点击音位可以检查每个音的答案。':filled===3?'3 / 3 已选好，点击「确认答案」或按 Enter 提交。':'已选 '+filled+' / 3 · 正在填写第 '+(slot+1)+' 音。点下方琴键选择；想修改可点上方音位。';
}else $('bass-help').hidden=true;
const el=$('choices');el.replaceChildren();if(['match','bass'].includes(mode)){pool.forEach((n,i)=>{const w=document.createElement('div');w.className='key-wrap'+(selection[slot]===n?' selected':'')+(done&&target[slot]===n?' correct':'');const k=document.createElement('button');k.className='key'+(names[n%12].includes('♯')?' sharp':'');k.textContent=note(n);k.setAttribute('aria-label','选择 '+note(n));k.onclick=()=>selectPracticeAnswer(i);const p=document.createElement('button');p.className='pick';p.textContent=(selection[slot]===n?'●':'○')+' 选 '+(i+1);p.disabled=done;p.onclick=()=>selectPracticeAnswer(i);const listen=document.createElement('button');listen.className='listen-key';listen.textContent='♫ 仅试听';listen.setAttribute('aria-label','仅试听 '+note(n));listen.onclick=()=>play([n]);w.append(k,p,listen);el.append(w)})}else{const labels=mode==='direction'?['1 · ↘ 更低','2 · → 相同','3 · ↗ 更高']:['1 · 大三和弦','2 · 小三和弦'];labels.forEach((label,i)=>{const w=document.createElement('div');w.className='key-wrap';if(mode==='chord'){const listen=document.createElement('button');listen.className='quiet';listen.textContent='♫ 试听示范';listen.style.marginBottom='10px';listen.onclick=()=>play(chord(i),true);w.append(listen)}const b=document.createElement('button');b.className='option'+(selection[0]===i?' selected':'')+(done&&expected()[0]===i?' correct':'');b.textContent=label;b.disabled=done;b.onclick=()=>selectPracticeAnswer(i);w.append(b);el.append(w)})}}
function finish(reveal=false){if(done)return;const answer=expected();if(!reveal&&answer.some((_,i)=>selection[i]===undefined)){$('feedback').textContent=mode==='bass'?'请先为三个位置都选一个音，也可以直接看答案。':'先选择一个答案，也可以直接看答案。';return}done=true;const correct=answer.every((n,i)=>selection[i]===n);if(!currentReview){stats.total++;if(correct&&!reveal)stats.correct++;}try{localStorage.setItem('ear-garden-stats',JSON.stringify(stats))}catch{}updateStats();recordAttempt(reveal,correct,answer);completePracticeQuestion(reveal,correct);const text=mode==='direction'?['更低','相同','更高'][answer[0]]:mode==='chord'?note(target[0])+' '+['大三和弦','小三和弦'][answer[0]]+'（'+chord(answer[0]).map(note).join(' · ')+'）':target.map(note).join(' → ');$('feedback').textContent=(reveal?'答案揭晓：':correct?'✓ 找到了！':'再比较一下。正确答案：')+text+(reveal||!correct?'。把你选的音和正确答案交替听几遍。':'。可以再听一遍，把这次感觉记下来。');$('submit').hidden=true;$('next').hidden=false;$('reveal').hidden=true;render();const review=$('review');review.hidden=false;review.replaceChildren();const caption=document.createElement('div');caption.textContent=mode==='chord'?'复听：先分解，再听合起来的和弦。':'复听：把声音与答案对应起来。';review.append(caption);const button=(label,fn)=>{const b=document.createElement('button');b.className='quiet';b.textContent=label;b.onclick=fn;review.append(b)};button('♫ 正确答案',()=>mode==='chord'?play(chord(target[1]),true):play(target));if(mode==='chord')button('♫ 分解和弦',()=>play(chord(target[1])));else if(selection.length&&selection.every(x=>x!==undefined)&&mode!=='direction')button('♫ 我的答案',()=>play(selection));if(mode==='bass')target.forEach((n,i)=>button('第 '+(i+1)+' 音 · '+note(n),()=>play([n])))}
$('play').onclick=()=>mode==='chord'?play(chord(target[1]),true):play(target);$('replay').onclick=()=>$('play').click();$('sound').onclick=()=>play([60,64,67]);$('submit').onclick=()=>finish();$('reveal').onclick=()=>finish(true);$('next').onclick=nextPracticeQuestion;$('difficulty').onchange=newQuestion;$('register').onchange=newQuestion;$('timbre').onchange=newQuestion;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));newQuestion()});initRecords();initPractice();newQuestion();
